urlset:

  {{ scheme }}://{{ host }}{% url 'home' %}
  {% now "Y-m-d" %}
  weekly
  1.0


  {{ scheme }}://{{ host }}{% url 'products' %}
  {% now "Y-m-d" %}
  daily
  0.9


  {{ scheme }}://{{ host }}{% url 'updates' %}
  {% now "Y-m-d" %}
  weekly
  0.8


  {{ scheme }}://{{ host }}{% url 'request_product' %}
  {% now "Y-m-d" %}
  monthly
  0.7

{% for product in products %}

  {{ scheme }}://{{ host }}{% url 'products' %}?product={{ product.id }}
  {{ product.created_at|date:"Y-m-d" }}
  monthly
  0.6

{% endfor %}
{% for update in updates %}

  {{ scheme }}://{{ host }}{% url 'updates' %}#update-{{ update.id }}
  {{ update.created_at|date:"Y-m-d" }}
  weekly
  0.5

{% endfor %}
